/// Distance above which a glyph isn't any known digit.
const MAX_DISTANCE: f32 = 0.30;

fn distance(a: &[f32], b: &[f32]) -> f32 {
    let n = GW * GH;
    let pixels: f32 = a[..n].iter().zip(&b[..n]).map(|(x, y)| (x - y).abs()).sum::<f32>() / n as f32;
    pixels + 0.5 * (a[n] - b[n]).abs()
}

/// A stack size and how sure the reading is (0–1).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Reading {
    pub value: u32,
    pub confidence: f32,
}

/// Reads the number in a cell's stack-size region; None when there is no number or a glyph is unknown.
pub fn read(region: &Rgba) -> Option<Reading> {
    let (gl, suspicious) = glyphs_checked(region);
    if gl.is_empty() || gl.len() > 4 {
        return None;
    }
    let mut value = 0u32;
    let mut confidence = 1f32;
    for g in &gl {
        let mut ranked: Vec<(f32, u32)> = TEMPLATES.iter().map(|(d, t)| (distance(g, t), *d)).collect();
        ranked.sort_by(|a, b| a.0.total_cmp(&b.0));
        let (best, digit) = ranked[0];
        if best > MAX_DISTANCE {
            return None;
        }
        let second = ranked.get(1).map(|r| r.0).unwrap_or(1.0);
        // Clear winner and close match → near 1.
        let c = ((second - best) / second.max(1e-3)).clamp(0.0, 1.0) * (1.0 - best / MAX_DISTANCE).clamp(0.0, 1.0);
        confidence = confidence.min(c.sqrt());
        value = value * 10 + digit;
    }
    if suspicious {
        // A digit may have been lost in the item art: keep the reading, but never as certain.
        confidence = confidence.min(0.2);
    }
    (value > 0).then_some(Reading { value, confidence })
}
